query GetCurrentQuality($tag: String!, $hour: DateTime!) {
  telemetryHourly(
    where: {
      dataPoint: { tag: { _eq: $tag } }
      periodAt: { _eq: $hour }
    }
    first: 1
  ) {
    edges {
      node {
        avg
      }
    }
  }
}

